macro.command:
const version = "13.0.58";
const FIREARMS = ["revolver", "musket", "pistol"];
const SOUNDS = {
  critHorn: "sounds/combat/epic-start-horn.ogg",
  initDrums: "sounds/drums.wav",
  damageOoh: "modules/midi-qol/sounds/fail1.wav"
};
const playSound = (src, volume = 0.8) => foundry.audio.AudioHelper.play({ src, volume, autoplay: true, loop: false });
try {
  // === Kinetic Battery: Bonus damage on firearm hit ===
  if (args[0].tag === "DamageBonus") {
    if (args[0].hitTargets.length === 0) return {};
    const baseItem = rolledItem?.system?.type?.baseItem;
    if (!FIREARMS.includes(baseItem)) return {};
    const charges = actor.getFlag("midi-qol", "thunderHeadCharges") || 0;
    if (charges <= 0) return {};
    await actor.setFlag("midi-qol", "thunderHeadCharges", 0);
    ChatMessage.create({
      content: `<p><strong>Kinetic Battery Discharge!</strong> ${charges} charge${charges !== 1 ? "s" : ""} expended for ${charges}d12 Force damage.</p>`,
      speaker: ChatMessage.getSpeaker({ actor })
    });
    return { damageRoll: `${charges}d12[force]`, flavor: "Kinetic Battery" };
  }

  // === Aero-Stabiliser: Advantage on firearm attacks from 60ft above ===
  if (args[0].tag === "OnUse" && args[0].macroPass === "preAttackRoll") {
    const baseItem = rolledItem?.system?.type?.baseItem;
    if (!FIREARMS.includes(baseItem)) return;
    const attackerToken = canvas.tokens.get(args[0].tokenId);
    const targetToken = args[0].targets?.[0]?.object;
    if (!attackerToken || !targetToken) return;
    const elevDiff = (attackerToken.document.elevation ?? 0) - (targetToken.document.elevation ?? 0);
    if (elevDiff >= 60) {
      workflow.advantage = true;
      workflow.attackAdvAttribution.add("Aero-Stabiliser (60ft above)");
    }
  }

  // === Hype-Man: Air-horn on critical hits ===
  if (args[0].tag === "OnUse" && args[0].macroPass === "postAttackRoll") {
    if (workflow.isCritical) {
      playSound(SOUNDS.critHorn, 1.0);
      ChatMessage.create({
        content: `<p><em>The broom blasts a stadium air-horn! <strong>BWAAAAAAH!</strong></em></p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    }
  }

  // === Hype-Man: Sympathetic OOH! on taking damage ===
  if (args[0].tag === "OnUse" && args[0].macroPass === "isDamaged") {
    playSound(SOUNDS.damageOoh, 0.6);
  }

  // === Hype-Man: War drums on combat start / Transfer effect setup ===
  if (args[0] === "on") {
    const lastArg = args[args.length - 1];
    const effectName = lastArg?.efData?.name ?? "";
    if (effectName === "Aero-Stabiliser") {
      const hookId = Hooks.on("combatStart", (combat) => {
        const combatant = combat.combatants.find(c => c.actorId === actor.id);
        if (combatant) {
          playSound(SOUNDS.initDrums, 0.8);
          ChatMessage.create({
            content: `<p><em>The Thunder-Head's bristles thrum with a rhythmic, war-drum beat!</em></p>`,
            speaker: ChatMessage.getSpeaker({ actor })
          });
        }
      });
      actor._thunderHeadCombatHook = hookId;
    }
  }

  // === Full-Auto Overdrive expired: Apply Stalled / Cleanup hooks ===
  if (args[0] === "off") {
    const lastArg = args[args.length - 1];
    const effectName = lastArg?.efData?.name ?? "";
    if (effectName === "Full-Auto Overdrive") {
      const stalledTemplate = macroItem.effects.find(e => e.name === "Stalled");
      if (stalledTemplate) {
        const effectData = stalledTemplate.toObject();
        effectData.origin = macroItem.uuid;
        effectData.disabled = false;
        effectData.flags.dae.dontApply = false;
        effectData.duration = {};
        await actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
        ui.notifications.warn("The Thunder-Head stalls! Speed 0 until you Kickstart it.");
      }
    }
    if (effectName === "Aero-Stabiliser" && actor._thunderHeadCombatHook) {
      Hooks.off("combatStart", actor._thunderHeadCombatHook);
      delete actor._thunderHeadCombatHook;
    }
  }
} catch (err) {
  console.error(`Thunder-Head Interceptor ${version}`, err);
}

macroData.command:
const version = "13.0.58";
try {
  if (args[0].tag === "OnUse" && args[0].macroPass === "postActiveEffects") {
    const token = canvas.tokens.get(args[0].tokenId);
    if (!token) return;
    // Apply Prone to targets that failed the save
    for (const target of args[0].failedSaves) {
      const targetActor = target.actor;
      if (targetActor) await targetActor.toggleStatusEffect("prone", { active: true });
    }
    // Backfire: DC 10 Str save
    ChatMessage.create({
      content: `<p><em>The broom bucks violently from the recoil...</em></p>`,
      speaker: ChatMessage.getSpeaker({ actor })
    });
    const saveRolls = await actor.rollSavingThrow({ability: "str", target: 10}, {}, { fastForward: true });
    const saveRoll = saveRolls?.[0];
    if (!saveRoll || saveRoll.total < 10) {
      const damageRoll = await new Roll("1d6[force]").evaluate();
      await MidiQOL.applyTokenDamage(
        [{ value: damageRoll.total, type: "force", properties: new Set() }],
        damageRoll.total,
        new Set([token]),
        macroItem,
        new Set()
      );
      // Gain Kinetic Battery charge (max 3)
      const charges = actor.getFlag("midi-qol", "thunderHeadCharges") || 0;
      const newCharges = Math.min(charges + 1, 3);
      await actor.setFlag("midi-qol", "thunderHeadCharges", newCharges);
      ChatMessage.create({
        content: `<p><strong>Backfire!</strong> ${damageRoll.total} Force damage from whiplash. Kinetic Battery: ${newCharges}/3 charges.</p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    } else {
      ChatMessage.create({
        content: `<p><strong>Backfire resisted!</strong> You brace against the whiplash. No charge stored.</p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    }
  }
} catch (err) {
  console.error(`Big Bang Recoil Backfire ${version}`, err);
}

const version = "13.0.58";
try {
  if (args[0].tag === "OnUse" && args[0].macroPass === "postActiveEffects") {
    const stalledEffect = actor.effects.find(e => e.name === "Stalled");
    if (stalledEffect) {
      await stalledEffect.delete();
      ChatMessage.create({
        content: `<p><strong>VROOOOM!</strong> The Thunder-Head Interceptor roars back to life with a deafening mechanical scream audible up to 300 feet!</p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    } else {
      ui.notifications.info("The broom isn't stalled.");
    }
  }
} catch (err) {
  console.error(`Kickstart ${version}`, err);
}
